#!/usr/bin/env node
// PreToolUse Claude Code hook for the roster subagents (a course pattern, not a built-in feature).
// Referenced from the `hooks:` frontmatter of .claude/agents/<agent>.md, so it runs only inside
// that agent. Zero dependencies, Node 22. Frappe edition.
//
// Usage (Claude Code hook command):
//   node agents/tool-guard.mjs write-scope <spec>... [!protectedSpec]...
//   node agents/tool-guard.mjs bash-allow <entry>...
//
// write-scope specs: a directory prefix ending in "/" (`sample-app/spice_lite/spice_lite/`), an exact
//   file, or a glob (`*` = one path segment, `**` = any depth), all relative to the project root.
// bash-allow entries (one allowed command shape each):
//   plain       `git diff`                       the command, optionally followed by any arguments
//   ask         `?bench --site test.localhost migrate`   never auto-allowed: the guard returns
//                                                permissionDecision "ask", so a human must approve
//   patterned   `tail {bench}/logs/**`           literal words, then path tokens that must stay inside
//               `grep ARG {bench}/logs/**`       the directory (`ARG` = one free argument, e.g. a
//               `node .claude/skills/x/scripts/** ...`   pattern; a trailing `...` = free arguments)
//   `{bench}` expands to $SPICE_BENCH_DIR or /home/user/frappe-bench.
//
// Reads the hook input JSON on stdin (tool_name, tool_input, cwd, agent_type, ...).
// Exit 0            = no objection (normal permission rules still apply afterwards).
// Exit 0 + JSON ask = permissionDecision "ask" (documented PreToolUse output).
// Exit 2            = block the tool call; stderr is shown to the agent.
// Fails closed: unreadable input or an unknown mode blocks.
import { readFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

export const DEFAULT_BENCH = '/home/user/frappe-bench';
export const benchDir = () => process.env.SPICE_BENCH_DIR || DEFAULT_BENCH;

// bench/site commands that are arbitrary code as Administrator, print secrets, open a DB shell,
// or destroy or rewrite a site. No roster agent may run them, whatever its allowlist says.
const BENCH_NEVER = [
  'console', 'execute', 'jupyter', 'db-console', 'mariadb', 'postgres', 'request', 'show-config',
  'drop-site', 'reinstall', 'restore', 'partial-restore', 'set-admin-password', 'set-password',
  'set-config', 'add-system-manager', 'add-user', 'browse', 'run-patch', 'destroy-all-sessions',
  'trim-database', 'trim-tables', 'clear-log-table', 'purge-jobs', 'trigger-scheduler-event',
  'uninstall-app', 'remove-from-installed-apps', 'new-site', 'install-app', 'import-doc', 'data-import',
  'bulk-rename', 'set-maintenance-mode', 'enable-scheduler', 'disable-scheduler', 'update', 'restart',
  'setup', 'remove-app', 'get-app', 'backup',
];
const benchNeverRe = new RegExp(`\\bbench\\b(\\s+--?[\\w-]+(\\s+(?!-)\\S+)?)*\\s+(${BENCH_NEVER.join('|')})(\\s|$)`);

// Commands no roster agent may run (CLAUDE.md rules 2 and 9), checked before any allowlist.
export const ALWAYS_DENY = [
  [benchNeverRe, 'bench console/execute/db shells, show-config, site-destroying or site-changing commands'],
  [/site_config\.json/, 'reading site_config.json or common_site_config.json (database password, encryption_key)'],
  [/\bgit\s+push\b/, 'git push'],
  [/\bgit\s+commit\b/, 'git commit'],
  [/\bgit\s+reset\s+--hard\b/, 'git reset --hard'],
  [/\bgit\s+clean\b/, 'git clean'],
  [/\bgit\s+(checkout|restore|stash|apply|am|rebase|merge|cherry-pick)\b/, 'git commands that change the working tree'],
  [/(^|&&|\|)\s*(sudo|su|doas)(\s|$)/, 'privilege change (sudo/su)'],
  [/(^|&&|\|)\s*(psql|mysql|mariadb|redis-cli)(\s|$)/, 'direct database or Redis client'],
  [/\brm\s+-[a-z]*r/i, 'recursive rm'],
  [/\b(curl|wget|nc|ssh|scp)\b/, 'network access'],
  // flags that turn an allowed read-only command into a writer or an arbitrary reader:
  [/\s--output(=|\s|$)/, 'git --output (writes a file)'],
  [/\s--no-index\b/, 'git diff --no-index (reads arbitrary paths, e.g. site_config.json)'],
  [/\s--ext-diff\b/, 'git --ext-diff (runs an external program)'],
  [/\s--junit-xml-output\b/, 'run-tests --junit-xml-output (writes a file anywhere)'],
];

// Shell metacharacters that could chain, substitute or redirect. `&&`, a single `|` between allowed
// commands, and the exact token `2>&1` are handled separately.
const FORBIDDEN_SHELL = [
  [/\n/, 'newline'], [/;/, ';'], [/`/, 'backtick'], [/\$\(/, '$( )'], [/\$\{/, '${ }'],
  [/\|\|/, '||'], [/>/, 'redirect >'], [/</, 'redirect <'], [/(?<!&)&(?!&)/, 'background &'],
];
// Options never allowed in a patterned (path-scoped) entry: follow forever, or read paths from a file.
const UNSAFE_OPTIONS = /^(-f|-F|--follow(=.*)?|--files0-from(=.*)?|-r|-R|--recursive|--dereference-recursive)$/;

// Quote-aware split on spaces (no escapes). Quotes are removed from the returned tokens.
export function tokenize(str) {
  const out = [];
  let cur = '', q = null, has = false;
  for (const ch of String(str)) {
    if (q) { if (ch === q) q = null; else cur += ch; continue; }
    if (ch === '"' || ch === "'") { q = ch; has = true; continue; }
    if (ch === ' ' || ch === '\t') { if (has || cur) out.push(cur); cur = ''; has = false; continue; }
    cur += ch;
  }
  if (q) return null; // unbalanced quote
  if (has || cur) out.push(cur);
  return out;
}

// A skill that runs `node ${CLAUDE_SKILL_DIR}/scripts/x.mjs` reaches Bash with the variable already
// substituted by Claude Code (normally an absolute path). Absolute paths INSIDE the project are
// rewritten to project-relative form, so one relative entry such as
// `python3 .claude/skills/run-tests/scripts/** ...` matches both. Paths outside the project are kept.
export function normalizeToken(tok, projectDir) {
  if (!projectDir || !path.isAbsolute(tok)) return tok;
  const rel = path.relative(path.resolve(projectDir), path.resolve(tok)).split(path.sep).join('/');
  if (!rel || rel.startsWith('..') || path.isAbsolute(rel)) return tok;
  return rel + (tok.endsWith('/') && !rel.endsWith('/') ? '/' : '');
}

export function parseEntry(raw) {
  let s = String(raw).trim();
  const ask = s.startsWith('?');
  if (ask) s = s.slice(1).trim();
  s = s.replaceAll('{bench}', benchDir());
  const toks = tokenize(s) || [];
  const patterned = toks.some((t) => t === 'ARG' || t === '...' || t.endsWith('/**'));
  return { raw, ask, text: toks.join(' '), toks, patterned };
}

const isUnder = (p, dir, projectDir) => {
  if (p.split('/').includes('..') || p.startsWith('~')) return false;
  const absDir = path.resolve(projectDir, dir);
  const abs = path.resolve(projectDir, p.replace(/\*.*$/, '') || '.');
  const rel = path.relative(absDir, abs);
  return rel === '' || (!rel.startsWith('..') && !path.isAbsolute(rel));
};

function matchPatterned(entry, toks, projectDir) {
  const pat = entry.toks;
  const special = (t) => t === 'ARG' || t === '...' || t.endsWith('/**');
  let j = 0;
  while (j < pat.length && !special(pat[j])) {
    if (toks[j] !== pat[j]) return false; // literal command words, in order
    j++;
  }
  const want = pat.slice(j);
  const used = new Array(want.length).fill(false);
  let w = 0;
  for (const t of toks.slice(j)) {
    if (want[w] === '...') return used.slice(0, w).every(Boolean);
    if (t.startsWith('-')) { if (UNSAFE_OPTIONS.test(t)) return false; continue; }
    if (/^\d+$/.test(t)) continue; // option values such as -n 200
    if (w >= want.length) return false; // an extra positional argument
    if (want[w] === 'ARG') { used[w] = true; w++; continue; }
    if (!isUnder(t, want[w].slice(0, -3), projectDir)) return false;
    used[w] = true;
    if (w + 1 < want.length) w++; // the last path spec may repeat (several log files)
  }
  return want.every((spec, k) => spec === '...' || used[k]);
}

export function checkBash(command, entries, projectDir) {
  const cmd = String(command ?? '').trim();
  if (!cmd) return { reason: 'empty command' };
  for (const [re, label] of ALWAYS_DENY) {
    if (re.test(cmd)) return { reason: `"${label}" is never allowed for any roster agent (CLAUDE.md rules 2 and 9: secrets stay unread; a human migrates shared sites, pushes and deploys)` };
  }
  const merged = cmd.replace(/(^|\s)2>&1(?=\s|$)/g, ' ');
  for (const [re, label] of FORBIDDEN_SHELL) {
    if (re.test(merged)) return { reason: `shell metacharacter ${label} is not allowed; run allowed commands joined only by && or |` };
  }
  const parsed = entries.map(parseEntry);
  let ask = null;
  const segments = merged.split(/&&|\|/).map((s) => s.trim());
  for (const seg of segments) {
    if (!seg) return { reason: 'empty command segment' };
    const raw = tokenize(seg);
    if (!raw) return { reason: `unbalanced quote in "${seg}"` };
    const toks = raw.map((t) => normalizeToken(t, projectDir));
    const text = toks.join(' ');
    const hit = parsed.find((e) => (e.patterned ? matchPatterned(e, toks, projectDir) : text === e.text || text.startsWith(e.text + ' ')));
    if (!hit) return { reason: `"${text}" is outside this agent's Bash allowlist: ${entries.map((p) => `"${p}"`).join(', ')}` };
    if (hit.ask) ask = hit.text;
  }
  return ask ? { ask: `"${ask}" needs a human decision (it changes the test site); approve or reject the prompt` } : null;
}

const globRe = (g) => new RegExp('^' + g.split('**').map((part) => part.split('*').map((x) => x.replace(/[.+?^${}()|[\]\\]/g, '\\$&')).join('[^/]*')).join('.*') + '$');

export function checkWrite(filePath, specs, projectDir, cwd) {
  if (!filePath) return 'no file_path in tool input';
  const allowed = specs.filter((s) => !s.startsWith('!'));
  const denied = specs.filter((s) => s.startsWith('!')).map((s) => s.slice(1));
  const abs = path.resolve(cwd || projectDir, filePath);
  const rel = path.relative(projectDir, abs).split(path.sep).join('/');
  if (rel === '' || rel.startsWith('..') || path.isAbsolute(rel)) return `${filePath} is outside the project directory`;
  if (/(^|\/)(common_)?site_config\.json$/.test(rel)) return `${rel} is a site config file (secrets)`;
  const matches = (p) => (p.includes('*') ? globRe(p).test(rel) : rel === p.replace(/\/$/, '') || rel.startsWith(p.endsWith('/') ? p : p + '/'));
  const hit = denied.find(matches);
  if (hit) return `${rel} is explicitly protected for this agent (${hit})`;
  if (!allowed.some(matches)) return `${rel} is outside this agent's write scope: ${allowed.join(', ')}`;
  return null;
}

function main() {
  const [mode, ...args] = process.argv.slice(2);
  let input;
  try {
    input = JSON.parse(readFileSync(0, 'utf8'));
  } catch {
    process.stderr.write('tool-guard: could not parse hook input JSON; blocking (fail closed)\n');
    process.exit(2);
  }
  const tool = input.tool_name;
  const ti = input.tool_input ?? {};
  const projectDir = process.env.CLAUDE_PROJECT_DIR || input.cwd || process.cwd();
  const who = input.agent_type ? `[${input.agent_type}] ` : '';
  let reason = null;
  if (mode === 'bash-allow') {
    if (tool !== 'Bash') process.exit(0);
    const r = checkBash(ti.command, args, projectDir);
    if (r?.ask) {
      process.stdout.write(JSON.stringify({ hookSpecificOutput: { hookEventName: 'PreToolUse', permissionDecision: 'ask', permissionDecisionReason: `tool-guard ${who}${r.ask}` } }) + '\n');
      process.exit(0);
    }
    reason = r?.reason ?? null;
  } else if (mode === 'write-scope') {
    if (!['Write', 'Edit', 'NotebookEdit'].includes(tool)) process.exit(0);
    reason = checkWrite(ti.file_path ?? ti.notebook_path, args, projectDir, input.cwd);
  } else {
    reason = `unknown mode "${mode}"; expected write-scope or bash-allow`;
  }
  if (reason) {
    process.stderr.write(`tool-guard ${who}blocked ${tool}: ${reason}. If the task needs this, stop and hand off with status: blocked.\n`);
    process.exit(2);
  }
  process.exit(0);
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) main();

// Tests for agents/tool-guard.mjs (Frappe edition). Run: node --test agents/tool-guard.test.mjs
// The allowlists below are the ones the roster agents use in .claude/agents/*.md; check-agents.test.mjs
// asserts that the agent files still contain them.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { checkBash, checkWrite, tokenize, DEFAULT_BENCH } from './tool-guard.mjs';

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(here, '..');
const guard = path.join(here, 'tool-guard.mjs');
const B = DEFAULT_BENCH;
delete process.env.SPICE_BENCH_DIR; // tests use the default bench path

function runHook(args, input, env = {}) {
  return spawnSync('node', [guard, ...args], {
    input: typeof input === 'string' ? input : JSON.stringify(input),
    env: { ...process.env, CLAUDE_PROJECT_DIR: root, SPICE_BENCH_DIR: '', ...env },
    encoding: 'utf8',
  });
}
const ok = (r, c) => assert.equal(r, null, `${c}: ${JSON.stringify(r)}`);
const blocked = (r, re, c) => { assert.ok(r?.reason, `${c}: expected a block, got ${JSON.stringify(r)}`); assert.match(r.reason, re, c); };

export const REVIEWER = ['git diff', 'git log', 'git show', 'git status'];
export const DEVELOPER = [
  'cd {bench}', 'bench --site test.localhost run-tests', 'CI=1 bench --site test.localhost run-tests', '?bench --site test.localhost migrate',
  'cd sample-app/spice_lite', 'python -m unittest discover -s spice_lite/tests/unit -t .',
  'python3 .claude/skills/run-tests/scripts/** ...', 'date -u', 'git diff', 'git status', 'git log',
];
export const SRE = [
  'cd {bench}', 'bench --site test.localhost doctor', 'bench --site test.localhost show-pending-jobs',
  'ls {bench}/logs/**', 'tail {bench}/logs/**', 'grep ARG {bench}/logs/**',
  'tail {bench}/sites/test.localhost/logs/**', 'grep ARG {bench}/sites/test.localhost/logs/**',
  'node .claude/skills/performance-review/scripts/** ...', 'node .claude/skills/production-rca/scripts/** ...',
  'git log', 'git diff', 'git status',
];

test('reviewer: read-only git passes; push, chaining and escaping flags do not', () => {
  for (const c of ['git diff main...HEAD -- sample-app', 'git diff --stat HEAD', 'git log --oneline -5', 'git status']) ok(checkBash(c, REVIEWER, root), c);
  blocked(checkBash('git push origin HEAD', REVIEWER, root), /git push/);
  blocked(checkBash('git diff | tee out.txt', REVIEWER, root), /"tee out.txt" is outside/);
  blocked(checkBash('git diff; rm -rf sample-app', REVIEWER, root), /recursive rm|;/);
  blocked(checkBash('git diff --output=/tmp/x', REVIEWER, root), /--output/);
  blocked(checkBash(`git diff --no-index /dev/null ${B}/sites/common_site_config.json`, REVIEWER, root), /site_config|no-index/);
  blocked(checkBash('git diff --no-index /dev/null .env', REVIEWER, root), /no-index/);
  blocked(checkBash('git checkout -- sample-app', REVIEWER, root), /change the working tree/);
  blocked(checkBash('git diff $(cat .env)', REVIEWER, root), /\$\(/);
});

test('developer: run-tests and unit tests pass, with && and a pipe into the run-tests parser', () => {
  ok(checkBash(`cd ${B} && bench --site test.localhost run-tests --app spice_lite`, DEVELOPER, root));
  ok(checkBash(`cd ${B} && bench --site test.localhost run-tests --module spice_lite.tests.test_fhir_api --test test_lastn_returns_latest_per_patient`, DEVELOPER, root));
  ok(checkBash(`cd ${B} && bench --site test.localhost run-tests --module spice_lite.tests.test_fhir_api 2>&1 | python3 ${root}/.claude/skills/run-tests/scripts/parse_bench_tests.py`, DEVELOPER, root));
  ok(checkBash(`cd ${B} && CI=1 bench --site test.localhost run-tests --app spice_lite`, DEVELOPER, root));
  blocked(checkBash(`cd ${B} && CI=1 bench --site test.localhost console`, DEVELOPER, root), /never allowed/);
  ok(checkBash('cd sample-app/spice_lite && python -m unittest discover -s spice_lite/tests/unit -t .', DEVELOPER, root));
  blocked(checkBash(`cd ${B} && bench --site test.localhost run-tests --app spice_lite &`, DEVELOPER, root), /background/);
  blocked(checkBash(`cd ${B} && bench --site mariadb.localhost run-tests --app spice_lite`, DEVELOPER, root), /outside this agent's Bash allowlist/);
  blocked(checkBash('bench --site test.localhost run-tests --junit-xml-output /tmp/x.xml', DEVELOPER, root), /junit-xml-output/);
  blocked(checkBash('git commit -m "wip"', DEVELOPER, root), /git commit/);
  blocked(checkBash('curl https://example.com', DEVELOPER, root), /network/);
  blocked(checkBash('pip install requests', DEVELOPER, root), /allowlist/);
});

test('bench console, execute, db shells and show-config are blocked for everyone, even if allow-listed', () => {
  const reckless = ['bench', 'cd {bench}', 'bench --site test.localhost'];
  for (const c of [
    'bench --site test.localhost console',
    `cd ${B} && bench --site test.localhost execute frappe.db.sql --args "['select 1']"`,
    'bench --verbose --site test.localhost execute spice_lite.demo.seed_demo',
    'bench --site test.localhost mariadb', 'bench --site test.localhost postgres', 'bench --site test.localhost db-console',
    'bench --site test.localhost show-config', 'bench drop-site test.localhost', 'bench --site test.localhost reinstall --yes',
    'bench --site test.localhost set-admin-password x', 'bench --site test.localhost backup', 'bench --site test.localhost jupyter',
    `cat ${B}/sites/test.localhost/site_config.json`, 'psql -h 127.0.0.1 -U postgres', 'redis-cli -p 11000 flushall', 'sudo -u frappe bench',
  ]) blocked(checkBash(c, reckless, root), /never allowed for any roster agent/, c);
});

test('migrate is never auto-allowed: an ask entry returns an ask decision, not null', () => {
  const r = checkBash(`cd ${B} && bench --site test.localhost migrate`, DEVELOPER, root);
  assert.match(r?.ask ?? '', /bench --site test\.localhost migrate" needs a human decision/);
  assert.match(checkBash('bench --site test.localhost migrate', ['bench --site test.localhost run-tests'], root).reason, /allowlist/, 'no ask entry: blocked');
  const hook = runHook(['bash-allow', ...DEVELOPER], { tool_name: 'Bash', tool_input: { command: `cd ${B} && bench --site test.localhost migrate` }, agent_type: 'developer' });
  assert.equal(hook.status, 0);
  const out = JSON.parse(hook.stdout);
  assert.equal(out.hookSpecificOutput.hookEventName, 'PreToolUse');
  assert.equal(out.hookSpecificOutput.permissionDecision, 'ask');
  assert.match(out.hookSpecificOutput.permissionDecisionReason, /\[developer\]/);
});

test('sre: bench diagnostics and path-scoped log reads pass; escapes and follow mode do not', () => {
  ok(checkBash(`cd ${B} && bench --site test.localhost doctor`, SRE, root));
  ok(checkBash(`cd ${B} && bench --site test.localhost show-pending-jobs`, SRE, root));
  ok(checkBash(`ls -la ${B}/logs/`, SRE, root));
  ok(checkBash(`tail -n 200 ${B}/logs/worker.error.log`, SRE, root));
  ok(checkBash(`tail -n 50 ${B}/logs/web.log ${B}/logs/worker.log`, SRE, root));
  ok(checkBash(`grep -c "RQ Job" ${B}/logs/*.log`, SRE, root));
  ok(checkBash(`grep -n -A 3 Traceback ${B}/sites/test.localhost/logs/frappe.log`, SRE, root));
  blocked(checkBash(`tail -f ${B}/logs/web.log`, SRE, root), /allowlist/);
  blocked(checkBash(`tail -n 5 ${B}/logs/../Procfile`, SRE, root), /allowlist/);
  blocked(checkBash(`tail -n 5 ${B}/logs/web.log /etc/passwd`, SRE, root), /allowlist/);
  blocked(checkBash(`grep -r password ${B}/logs/`, SRE, root), /allowlist/);
  blocked(checkBash(`grep -c key ${B}/sites/common_site_config.json`, SRE, root), /site_config/);
  blocked(checkBash(`cd ${B} && bench --site test.localhost purge-jobs`, SRE, root), /never allowed/);
  blocked(checkBash('kubectl scale deploy/spice --replicas=4', SRE, root), /allowlist/);
});

test('{bench} follows SPICE_BENCH_DIR, so a learner bench elsewhere works without editing agents', () => {
  const r = runHook(['bash-allow', ...SRE], { tool_name: 'Bash', tool_input: { command: 'tail -n 20 /opt/bench/spice/logs/worker.log' } }, { SPICE_BENCH_DIR: '/opt/bench/spice' });
  assert.equal(r.status, 0, r.stderr);
  const d = runHook(['bash-allow', ...SRE], { tool_name: 'Bash', tool_input: { command: `tail -n 20 ${B}/logs/worker.log` } }, { SPICE_BENCH_DIR: '/opt/bench/spice' });
  assert.equal(d.status, 2);
});

test('${CLAUDE_SKILL_DIR}-expanded absolute paths inside the project match relative entries', () => {
  const rel = 'node .claude/skills/production-rca/scripts/build-timeline.mjs evidence/worker.log --collapse';
  ok(checkBash(rel, SRE, root));
  ok(checkBash(`node ${root}/.claude/skills/production-rca/scripts/build-timeline.mjs evidence/worker.log`, SRE, root));
  ok(checkBash(`node "${root}/.claude/skills/performance-review/scripts/count-queries.mjs" /tmp/lastn.log`, SRE, root));
  blocked(checkBash('node /tmp/evil/.claude/skills/production-rca/scripts/build-timeline.mjs', SRE, root), /allowlist/);
  blocked(checkBash(`node ${root}/../x/.claude/skills/production-rca/scripts/build-timeline.mjs`, SRE, root), /allowlist/);
  blocked(checkBash(`node ${root}/.claude/skills/production-rca/scripts/../../../../agents/tool-guard.mjs`, SRE, root), /allowlist/);
});

test('write-scope: prefixes, globs for DocType test files, protected paths, site_config and escapes', () => {
  const dev = ['sample-app/spice_lite/spice_lite/', '.ai-sdlc/runs/', '!sample-app/spice_lite/spice_lite/patches/v0_1/'];
  ok(checkWrite('sample-app/spice_lite/spice_lite/api/fhir.py', dev, root, root));
  ok(checkWrite('sample-app/spice_lite/spice_lite/clinical/doctype/sl_patient/sl_patient.json', dev, root, root));
  ok(checkWrite(path.join(root, '.ai-sdlc/runs/r1/04-developer.md'), dev, root, root));
  assert.match(checkWrite('sample-app/spice_lite/spice_lite/patches/v0_1/backfill_patient_country.py', dev, root, root), /protected/);
  assert.match(checkWrite('sample-app/spice_lite/pyproject.toml', dev, root, root), /outside this agent's write scope/);
  assert.match(checkWrite('../outside.txt', dev, root, root), /outside the project/);
  assert.match(checkWrite('sample-app/spice_lite/spice_lite/../../../CLAUDE.md', dev, root, root), /write scope/);
  assert.match(checkWrite('sample-app/spice_lite/spice_lite/site_config.json', dev, root, root), /site config/);
  const tester = ['sample-app/spice_lite/spice_lite/tests/', 'sample-app/spice_lite/spice_lite/**/doctype/*/test_*.py', '.ai-sdlc/runs/'];
  ok(checkWrite('sample-app/spice_lite/spice_lite/tests/test_fhir_api.py', tester, root, root));
  ok(checkWrite('sample-app/spice_lite/spice_lite/clinical/doctype/sl_observation/test_sl_observation.py', tester, root, root));
  assert.match(checkWrite('sample-app/spice_lite/spice_lite/clinical/doctype/sl_observation/sl_observation.py', tester, root, root), /write scope/);
  assert.match(checkWrite('sample-app/spice_lite/spice_lite/clinical/doctype/sl_observation/sl_observation.json', tester, root, root), /write scope/);
});

